def totalNumbers(digits: List[int]) -> int:
    unique_numbers = set()
    even_digits = [d for d in digits if d % 2 == 0]
    for last_digit in even_digits:
        for first_digit in digits:
            if first_digit == last_digit or first_digit == 0:
                continue
            remaining_digits = digits.copy()
            remaining_digits.remove(first_digit)
            remaining_digits.remove(last_digit)
            for second_digit in remaining_digits:
                num = first_digit * 100 + second_digit * 10 + last_digit
                unique_numbers.add(num)
    return len(unique_numbers)

