def maximumCoins(coins: List[List[int]], k: int) -> int:
    max_coins = 0
    # To keep track of the coin counts at each position
    coin_map = {}

    # Populate the coin_map with the coins in each range
    for l, r, c in coins:
        for pos in range(l, r + 1):
            if pos in coin_map:
                coin_map[pos] += c
            else:
                coin_map[pos] = c

    # Convert the keys of the coin_map to a sorted list of positions
    positions = sorted(coin_map.keys())
    # Calculate the maximum coins in any window of size k
    current_coins = 0
    left = 0

    for right in range(len(positions)):
        # Add the coins at the current position to the current total
        current_coins += coin_map[positions[right]]
        # Check if we need to slide the window
        while positions[right] - positions[left] + 1 > k:
            current_coins -= coin_map[positions[left]]
            left += 1
        # Update max_coins if the current window is valid
        if positions[right] - positions[left] + 1 <= k:
            max_coins = max(max_coins, current_coins)

    return max_coins

